insert into public.proyectos_ideas (id, area, areas2, titulo, resumen, tipo, tiempo, horas, etiquetas, intencion, datos, prog, busca, ficha, orden) values
('analizando-experiencias-de-participacion-comunitaria-e-instituci','derecho',array['sociedad']::text[],'Analizando experiencias de participación comunitaria e institucional','Estudia experiencias reales de participación, desde comités vecinales hasta presupuestos participativos, y descubre qué las hace funcionar o fracasar.','Investigación','~24 h',24,array['Experiencias','Comunidad']::text[],array['investigar']::text[],'publicos',NULL,'ciencias politicas sociologia trabajo social antropologia derecho administracion geografia comunicaciones investigacion cualitativa. analisis comparativo. entrevistas. redaccion de informes. informes publicos. una guia de entrevista. un editor de documentos.',$a53sld${"id": "analizando-experiencias-de-participacion-comunitaria-e-instituci", "area": "derecho", "areas2": ["sociedad"], "titulo": "Analizando experiencias de participación comunitaria e institucional", "resumen": "Estudia experiencias reales de participación, desde comités vecinales hasta presupuestos participativos, y descubre qué las hace funcionar o fracasar.", "tipo": "Investigación", "tiempo": "~24 h", "horas": 24, "etiquetas": ["Experiencias", "Comunidad"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Ciencias Políticas", "Sociología", "Trabajo Social", "Antropología", "Derecho", "Administración", "Geografía", "Comunicaciones"], "problema": ["En muchas comunidades ya existen formas de participar: juntas vecinales, comités, ollas comunes, mesas de diálogo. Algunas logran resultados y otras se desgastan. No siempre se estudia por qué.", "Analizar esas experiencias permite aprender lecciones para organizar mejor la participación."], "desarrollar": ["Con información pública, reportes o entrevistas con consentimiento, describe tres experiencias de participación, sus objetivos, quiénes participan, cómo se decide y qué resultados lograron.", "Compara las experiencias, identifica los factores que ayudaron o dificultaron la participación, como información, tiempo, confianza y acceso, y escribe tres lecciones."], "ampliaciones": [{"titulo": "Barreras", "aporta": "estudia qué impide participar a ciertos grupos."}, {"titulo": "Indicadores de éxito", "aporta": "propón cómo medir si una experiencia funciona."}, {"titulo": "Voces diversas", "aporta": "compara perspectivas de participantes y de la institución."}], "objetivos": ["Describir experiencias participativas.", "Compararlas.", "Identificar factores de éxito y barreras.", "Extraer lecciones."], "habilidades": ["Investigación cualitativa.", "Análisis comparativo.", "Entrevistas.", "Redacción de informes."], "herramientas": ["Informes públicos.", "Una guía de entrevista.", "Un editor de documentos."], "lineamientos": ["Mantén una mirada neutral: explica mecanismos y procedimientos, sin opinar sobre partidos, candidatos ni gestiones concretas.", "Pide consentimiento si entrevistas a personas, no registres datos personales y protege a los participantes.", "Verifica siempre en fuentes oficiales que la información siga vigente y cita su fecha, porque las normas y los procedimientos cambian."], "otroSector": "El mismo análisis sirve para evaluar experiencias de participación en colegios, universidades o empresas."}$a53sld$::jsonb,55),
('materiales-informativos-sobre-participacion-ciudadana','derecho',array['arte','educacion']::text[],'Materiales informativos sobre participación ciudadana','Diseña materiales atractivos y fáciles de entender, como afiches, videos o tarjetas, que expliquen cómo participar en un mecanismo concreto de participación ciudadana.','Prototipo','~22 h',22,array['Comunicación','Participación']::text[],array['crear']::text[],'publicos',NULL,'comunicaciones diseno ciencias politicas derecho educacion sociologia ingenieria de sistemas trabajo social diseno grafico. comunicacion clara. pruebas con usuarios. pensamiento civico. un editor de diseno. un editor de video. un formulario de opinion.',$a54sld${"id": "materiales-informativos-sobre-participacion-ciudadana", "area": "derecho", "areas2": ["arte", "educacion"], "titulo": "Materiales informativos sobre participación ciudadana", "resumen": "Diseña materiales atractivos y fáciles de entender, como afiches, videos o tarjetas, que expliquen cómo participar en un mecanismo concreto de participación ciudadana.", "tipo": "Prototipo", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Comunicación", "Participación"], "intencion": ["crear"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Comunicaciones", "Diseño", "Ciencias Políticas", "Derecho", "Educación", "Sociología", "Ingeniería de Sistemas", "Trabajo Social"], "problema": ["La información sobre participación existe, pero suele ser larga, formal y poco atractiva. Si nadie la lee, nadie participa. Los materiales bien diseñados acercan los mecanismos a quienes más lo necesitan.", "Diseñar para un público concreto, como jóvenes o vecinos mayores, aumenta su efecto."], "desarrollar": ["Elige un mecanismo de participación y un público específico, define el mensaje principal y crea un conjunto de materiales, por ejemplo un afiche, una infografía y un video de un minuto.", "Prueba los materiales con cinco personas del público objetivo, mide si entendieron qué hacer y cómo, y mejora con sus comentarios."], "ampliaciones": [{"titulo": "Campaña corta", "aporta": "planifica cómo difundir los materiales en tres canales."}, {"titulo": "Accesibilidad", "aporta": "adapta los materiales para personas con discapacidad visual o auditiva."}, {"titulo": "Versión en otro idioma", "aporta": "adapta a una lengua originaria."}], "objetivos": ["Definir un público y un mensaje.", "Diseñar materiales claros.", "Probarlos con usuarios.", "Mejorarlos."], "habilidades": ["Diseño gráfico.", "Comunicación clara.", "Pruebas con usuarios.", "Pensamiento cívico."], "herramientas": ["Un editor de diseño.", "Un editor de video.", "Un formulario de opinión."], "lineamientos": ["Mantén una mirada neutral: explica mecanismos y procedimientos, sin opinar sobre partidos, candidatos ni gestiones concretas.", "Verifica siempre en fuentes oficiales que la información siga vigente y cita su fecha, porque las normas y los procedimientos cambian.", "Usa imágenes propias o libres y no incluyas rostros de personas sin permiso."], "otroSector": "La misma técnica sirve para campañas de salud, de ambiente o de seguridad."}$a54sld$::jsonb,56),
('que-derechos-tiene-una-persona-al-participar-en-una-consulta-o-m','derecho',array['sociedad']::text[],'¿Qué derechos tiene una persona al participar en una consulta o mecanismo de participación?','Explica qué derechos tienen las personas al participar en una consulta o en un mecanismo de participación, como recibir información, expresarse, estar protegidas y conocer el resultado.','Guía','~16 h',16,array['Derechos','Consultas']::text[],array['investigar']::text[],'publicos',NULL,'derecho ciencias politicas sociologia trabajo social educacion administracion comunicaciones antropologia lectura de normas. analisis de casos. redaccion clara. pensamiento civico. portales oficiales. un editor de documentos. casos inventados.',$a55sld${"id": "que-derechos-tiene-una-persona-al-participar-en-una-consulta-o-m", "area": "derecho", "areas2": ["sociedad"], "titulo": "¿Qué derechos tiene una persona al participar en una consulta o mecanismo de participación?", "resumen": "Explica qué derechos tienen las personas al participar en una consulta o en un mecanismo de participación, como recibir información, expresarse, estar protegidas y conocer el resultado.", "tipo": "Guía", "tiempo": "~16 h", "horas": 16, "etiquetas": ["Derechos", "Consultas"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Ciencias Políticas", "Sociología", "Trabajo Social", "Educación", "Administración", "Comunicaciones", "Antropología"], "problema": ["Participar implica derechos: a recibir información previa, a opinar sin represalias, a conocer cómo se usarán las opiniones y a enterarse del resultado. Pero si no se conocen, es difícil exigirlos.", "También hay deberes, como respetar a los demás y usar los canales."], "desarrollar": ["Con fuentes oficiales, resume los derechos y deberes de los participantes en consultas, audiencias y otros mecanismos, y elabora una lista clara para cada uno.", "Redacta tres escenarios inventados donde se vulnera o respeta algún derecho de participación y explica qué se podría hacer."], "ampliaciones": [{"titulo": "Pueblos indígenas", "aporta": "explica el derecho a consulta previa y sus diferencias."}, {"titulo": "Participación de menores", "aporta": "describe cómo se garantiza la voz de niños y adolescentes."}, {"titulo": "Lista de verificación", "aporta": "crea una lista para evaluar si una consulta es adecuada."}], "objetivos": ["Conocer derechos del participante.", "Aplicarlos a escenarios.", "Elaborar una lista clara.", "Explicar con sencillez."], "habilidades": ["Lectura de normas.", "Análisis de casos.", "Redacción clara.", "Pensamiento cívico."], "herramientas": ["Portales oficiales.", "Un editor de documentos.", "Casos inventados."], "lineamientos": ["Mantén una mirada neutral: explica mecanismos y procedimientos, sin opinar sobre partidos, candidatos ni gestiones concretas.", "Verifica siempre en fuentes oficiales que la información siga vigente y cita su fecha, porque las normas y los procedimientos cambian.", "Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a la entidad competente o a un abogado."], "otroSector": "La misma guía sirve para consultas internas en universidades, empresas o asociaciones."}$a55sld$::jsonb,57),
('como-puede-un-ciudadano-presentar-una-iniciativa-o-propuesta-ant','derecho',array['ciudades','sociedad']::text[],'¿Cómo puede un ciudadano presentar una iniciativa o propuesta ante su municipalidad?','Aprende cómo se presenta una propuesta a una municipalidad, qué forma debe tener, ante quién se entrega, cómo se da seguimiento y cómo aumentar sus posibilidades de ser atendida.','Guía','~22 h',22,array['Iniciativas','Municipalidad']::text[],array['crear','resolver']::text[],'publicos',NULL,'derecho ciencias politicas arquitectura administracion trabajo social sociologia comunicaciones ingenieria civil redaccion formal. diseno de propuestas. estimacion de costos. comunicacion civica. portales de la municipalidad. un editor de documentos. hoja de calculo.',$a56sld${"id": "como-puede-un-ciudadano-presentar-una-iniciativa-o-propuesta-ant", "area": "derecho", "areas2": ["ciudades", "sociedad"], "titulo": "¿Cómo puede un ciudadano presentar una iniciativa o propuesta ante su municipalidad?", "resumen": "Aprende cómo se presenta una propuesta a una municipalidad, qué forma debe tener, ante quién se entrega, cómo se da seguimiento y cómo aumentar sus posibilidades de ser atendida.", "tipo": "Guía", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Iniciativas", "Municipalidad"], "intencion": ["crear", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Ciencias Políticas", "Arquitectura", "Administración", "Trabajo Social", "Sociología", "Comunicaciones", "Ingeniería Civil"], "problema": ["Muchas ideas valiosas de vecinos, como arreglar un parque o crear una feria, se quedan en conversaciones porque nadie sabe cómo presentarlas formalmente. Una propuesta mal planteada se pierde en un escritorio.", "Saber cómo estructurarla, con diagnóstico, costo y beneficiarios, mejora sus opciones."], "desarrollar": ["Con fuentes oficiales y normas locales, describe los canales por los que un ciudadano puede presentar una propuesta, qué datos debe incluir y qué respuesta puede esperar.", "Redacta un ejemplo completo de propuesta inventada para un problema de barrio, con diagnóstico, objetivo, costo aproximado y beneficiarios, y una lista de errores frecuentes."], "ampliaciones": [{"titulo": "Con firmas", "aporta": "explica cómo reunir y presentar apoyo de vecinos."}, {"titulo": "Presupuesto participativo", "aporta": "enlaza la propuesta con ese mecanismo."}, {"titulo": "Seguimiento", "aporta": "diseña una hoja para registrar fechas y respuestas."}], "objetivos": ["Conocer canales de propuesta.", "Estructurar una propuesta convincente.", "Estimar costos y beneficiarios.", "Dar seguimiento."], "habilidades": ["Redacción formal.", "Diseño de propuestas.", "Estimación de costos.", "Comunicación cívica."], "herramientas": ["Portales de la municipalidad.", "Un editor de documentos.", "Hoja de cálculo."], "lineamientos": ["Mantén una mirada neutral: explica mecanismos y procedimientos, sin opinar sobre partidos, candidatos ni gestiones concretas.", "Verifica siempre en fuentes oficiales que la información siga vigente y cita su fecha, porque las normas y los procedimientos cambian.", "Presenta la propuesta como un ejercicio, sin enviar documentos con datos reales sin tu decisión consciente."], "otroSector": "La misma guía sirve para presentar propuestas a una universidad, a una empresa o a una asociación."}$a56sld$::jsonb,58),
('como-funciona-una-audiencia-publica-y-que-oportunidades-de-parti','derecho',array['sociedad']::text[],'¿Cómo funciona una audiencia pública y qué oportunidades de participación ofrece?','Explica cómo se convoca y se desarrolla una audiencia pública, quién puede intervenir, cómo preparar una intervención y qué pasa con lo que se dice.','Guía','~18 h',18,array['Audiencias públicas','Participación']::text[],array['investigar','crear']::text[],'publicos',NULL,'ciencias politicas derecho sociologia comunicaciones administracion trabajo social ingenieria ambiental educacion lectura de normas. expresion oral y escrita. preparacion de intervenciones. pensamiento civico. portales oficiales. un editor de documentos. un editor de presentaciones.',$a57sld${"id": "como-funciona-una-audiencia-publica-y-que-oportunidades-de-parti", "area": "derecho", "areas2": ["sociedad"], "titulo": "¿Cómo funciona una audiencia pública y qué oportunidades de participación ofrece?", "resumen": "Explica cómo se convoca y se desarrolla una audiencia pública, quién puede intervenir, cómo preparar una intervención y qué pasa con lo que se dice.", "tipo": "Guía", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Audiencias públicas", "Participación"], "intencion": ["investigar", "crear"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Ciencias Políticas", "Derecho", "Sociología", "Comunicaciones", "Administración", "Trabajo Social", "Ingeniería Ambiental", "Educación"], "problema": ["Una audiencia pública es un espacio donde las personas pueden opinar sobre decisiones que las afectan, como una obra, una norma o un presupuesto. Pero muchas veces se desconoce cuándo se convocan, cómo inscribirse y cómo prepararse.", "Conocer su funcionamiento permite aprovecharlas y no dejar la participación en manos de pocos."], "desarrollar": ["Con fuentes oficiales, describe qué es una audiencia pública, cuándo se convoca, cómo se anuncia, quién interviene y qué efecto tiene.", "Prepara una guía con pasos para participar, una plantilla de intervención de dos minutos sobre un tema inventado y un ejemplo de acta."], "ampliaciones": [{"titulo": "Asistir como observador", "aporta": "con permiso y si está abierta, asiste y registra cómo se desarrolla."}, {"titulo": "Participación virtual", "aporta": "explica cómo cambian las audiencias en línea."}, {"titulo": "Tras la audiencia", "aporta": "analiza cómo se informan los resultados."}], "objetivos": ["Conocer el funcionamiento de las audiencias.", "Preparar una intervención.", "Entender sus resultados.", "Explicar con claridad."], "habilidades": ["Lectura de normas.", "Expresión oral y escrita.", "Preparación de intervenciones.", "Pensamiento cívico."], "herramientas": ["Portales oficiales.", "Un editor de documentos.", "Un editor de presentaciones."], "lineamientos": ["Mantén una mirada neutral: explica mecanismos y procedimientos, sin opinar sobre partidos, candidatos ni gestiones concretas.", "Verifica siempre en fuentes oficiales que la información siga vigente y cita su fecha, porque las normas y los procedimientos cambian.", "Si asistes a una audiencia real, respeta las reglas del evento y no grabes sin autorización."], "otroSector": "La misma guía sirve para asambleas, juntas directivas o consultas de una organización."}$a57sld$::jsonb,59),
('rendicion-de-cuentas-que-informacion-debe-publicar-una-instituci','derecho',array['sociedad','tecnologia']::text[],'Rendición de cuentas: ¿qué información debe publicar una institución pública?','Descubre qué información debe publicar una institución pública sobre su gestión, como presupuesto, contratos, personal y resultados, y revisa si un portal la cumple de forma clara.','Análisis','~22 h',22,array['Rendición de cuentas','Transparencia']::text[],array['investigar']::text[],'publicos',NULL,'derecho ciencias politicas administracion contabilidad economia ingenieria de sistemas comunicaciones sociologia lectura de normas de transparencia. evaluacion de portales. analisis de datos publicos. redaccion neutral. portales de transparencia. hoja de calculo. un editor de informes.',$a58sld${"id": "rendicion-de-cuentas-que-informacion-debe-publicar-una-instituci", "area": "derecho", "areas2": ["sociedad", "tecnologia"], "titulo": "Rendición de cuentas: ¿qué información debe publicar una institución pública?", "resumen": "Descubre qué información debe publicar una institución pública sobre su gestión, como presupuesto, contratos, personal y resultados, y revisa si un portal la cumple de forma clara.", "tipo": "Análisis", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Rendición de cuentas", "Transparencia"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Ciencias Políticas", "Administración", "Contabilidad", "Economía", "Ingeniería de Sistemas", "Comunicaciones", "Sociología"], "problema": ["Las instituciones públicas deben informar a la ciudadanía sobre cómo usan sus recursos y qué logran. Pero no siempre se publica toda la información, o está en formatos difíciles de entender.", "Una lista de verificación permite ver qué se publica y qué falta."], "desarrollar": ["Con las normas de transparencia, elabora una lista de la información que debe publicar una institución, y revisa el portal de una institución elegida para ver qué está disponible, actualizado y es comprensible.", "Califica cada ítem con un semáforo, resume los resultados en un informe neutral y propón cómo mejorar la presentación de la información."], "ampliaciones": [{"titulo": "Comparar instituciones", "aporta": "aplica la lista a dos instituciones similares."}, {"titulo": "Datos abiertos", "aporta": "revisa si los datos pueden descargarse y reutilizarse."}, {"titulo": "Resumen para ciudadanos", "aporta": "crea una versión fácil de entender de un informe de gestión."}], "objetivos": ["Conocer obligaciones de transparencia.", "Elaborar una lista de verificación.", "Evaluar un portal.", "Informar de forma neutral."], "habilidades": ["Lectura de normas de transparencia.", "Evaluación de portales.", "Análisis de datos públicos.", "Redacción neutral."], "herramientas": ["Portales de transparencia.", "Hoja de cálculo.", "Un editor de informes."], "lineamientos": ["Mantén una mirada neutral: explica mecanismos y procedimientos, sin opinar sobre partidos, candidatos ni gestiones concretas.", "Verifica siempre en fuentes oficiales que la información siga vigente y cita su fecha, porque las normas y los procedimientos cambian.", "Presenta tus hallazgos como una descripción y no como una acusación, y cita las fechas de consulta."], "otroSector": "La misma lista sirve para evaluar la transparencia de una universidad, una empresa o una organización social."}$a58sld$::jsonb,60),
('vigilancia-ciudadana-como-seguir-el-cumplimiento-de-compromisos','derecho',array['sociedad','ciudades']::text[],'Vigilancia ciudadana: ¿cómo seguir el cumplimiento de compromisos de una institución?','Diseña un sistema sencillo para seguir si una institución cumple un compromiso público, como una obra, un servicio o una meta, con indicadores, fuentes y fechas.','Plan','~24 h',24,array['Vigilancia','Compromisos']::text[],array['crear','investigar']::text[],'publicos',NULL,'ciencias politicas derecho sociologia administracion ingenieria de sistemas estadistica comunicaciones trabajo social seguimiento de indicadores. busqueda de informacion publica. visualizacion. comunicacion civica. portales de transparencia. hoja de calculo. un editor de tableros.',$a59sld${"id": "vigilancia-ciudadana-como-seguir-el-cumplimiento-de-compromisos", "area": "derecho", "areas2": ["sociedad", "ciudades"], "titulo": "Vigilancia ciudadana: ¿cómo seguir el cumplimiento de compromisos de una institución?", "resumen": "Diseña un sistema sencillo para seguir si una institución cumple un compromiso público, como una obra, un servicio o una meta, con indicadores, fuentes y fechas.", "tipo": "Plan", "tiempo": "~24 h", "horas": 24, "etiquetas": ["Vigilancia", "Compromisos"], "intencion": ["crear", "investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Ciencias Políticas", "Derecho", "Sociología", "Administración", "Ingeniería de Sistemas", "Estadística", "Comunicaciones", "Trabajo Social"], "problema": ["Las instituciones anuncian obras, programas y metas, pero con el tiempo es difícil saber si se cumplieron. La vigilancia ciudadana consiste en dar seguimiento con información, y no solo con críticas.", "Un método claro de seguimiento hace más fácil informarse y dialogar con las autoridades."], "desarrollar": ["Elige un compromiso público de ejemplo, como una obra o un programa, define indicadores, como avance, plazos y presupuesto, y busca en fuentes públicas el estado actual.", "Crea una ficha de seguimiento con semáforo y fechas, y propón cómo comunicar los hallazgos de forma constructiva a la institución y a la comunidad."], "ampliaciones": [{"titulo": "Tablero", "aporta": "convierte la ficha en un tablero simple."}, {"titulo": "Alertas de retraso", "aporta": "define cuándo un retraso es preocupante."}, {"titulo": "Aliados", "aporta": "identifica organizaciones que hacen vigilancia ciudadana."}], "objetivos": ["Definir indicadores de cumplimiento.", "Buscar información pública.", "Diseñar una ficha de seguimiento.", "Comunicar de forma constructiva."], "habilidades": ["Seguimiento de indicadores.", "Búsqueda de información pública.", "Visualización.", "Comunicación cívica."], "herramientas": ["Portales de transparencia.", "Hoja de cálculo.", "Un editor de tableros."], "lineamientos": ["Mantén una mirada neutral: explica mecanismos y procedimientos, sin opinar sobre partidos, candidatos ni gestiones concretas.", "Verifica siempre en fuentes oficiales que la información siga vigente y cita su fecha, porque las normas y los procedimientos cambian.", "Usa información pública verificable y evita publicar acusaciones: describe hechos y fuentes."], "otroSector": "El mismo método sirve para dar seguimiento a promesas de proveedores, de proyectos de una empresa o de metas de una organización."}$a59sld$::jsonb,61),
('responsabilidades-de-la-ciudadania-en-los-procesos-electorales','derecho',array['sociedad','educacion']::text[],'Responsabilidades de la ciudadanía en los procesos electorales','Explica qué responsabilidades tiene una persona antes, durante y después de una elección, como informarse, votar, ser miembro de mesa y respetar las reglas, en una guía neutral y clara.','Guía','~16 h',16,array['Elecciones','Deberes ciudadanos']::text[],array['investigar','crear']::text[],'publicos',NULL,'ciencias politicas derecho sociologia educacion comunicaciones administracion trabajo social estadistica lectura de normas electorales. sintesis. diseno de guias. comunicacion neutral. portales de los organismos electorales. un editor de infografias. un editor de lineas de tiempo.',$a60sld${"id": "responsabilidades-de-la-ciudadania-en-los-procesos-electorales", "area": "derecho", "areas2": ["sociedad", "educacion"], "titulo": "Responsabilidades de la ciudadanía en los procesos electorales", "resumen": "Explica qué responsabilidades tiene una persona antes, durante y después de una elección, como informarse, votar, ser miembro de mesa y respetar las reglas, en una guía neutral y clara.", "tipo": "Guía", "tiempo": "~16 h", "horas": 16, "etiquetas": ["Elecciones", "Deberes ciudadanos"], "intencion": ["investigar", "crear"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Ciencias Políticas", "Derecho", "Sociología", "Educación", "Comunicaciones", "Administración", "Trabajo Social", "Estadística"], "problema": ["Participar en elecciones es más que votar: incluye informarse, conocer las reglas, cumplir obligaciones como ser miembro de mesa y respetar los resultados. Muchas personas desconocen estas responsabilidades.", "Entenderlas ayuda a que los procesos electorales funcionen con orden y confianza."], "desarrollar": ["Con fuentes oficiales, resume los derechos y deberes del ciudadano en un proceso electoral, desde el padrón hasta el conteo, y arma una línea de tiempo con las acciones que le corresponden en cada etapa.", "Diseña una guía breve y neutral, con preguntas frecuentes, y pruébala con cinco personas para ver si resuelve sus dudas."], "ampliaciones": [{"titulo": "Miembro de mesa", "aporta": "explica qué hace y cómo se sortea."}, {"titulo": "Información confiable", "aporta": "enseña a identificar fuentes confiables sobre elecciones."}, {"titulo": "Primer voto", "aporta": "adapta la guía para quienes votan por primera vez."}], "objetivos": ["Conocer responsabilidades electorales.", "Ordenar el proceso en etapas.", "Diseñar una guía neutral.", "Probarla con usuarios."], "habilidades": ["Lectura de normas electorales.", "Síntesis.", "Diseño de guías.", "Comunicación neutral."], "herramientas": ["Portales de los organismos electorales.", "Un editor de infografías.", "Un editor de líneas de tiempo."], "lineamientos": ["Mantén una mirada neutral: explica mecanismos y procedimientos, sin opinar sobre partidos, candidatos ni gestiones concretas.", "Verifica siempre en fuentes oficiales que la información siga vigente y cita su fecha, porque las normas y los procedimientos cambian.", "No incluyas propaganda ni opiniones sobre partidos o candidatos, y no hagas llamados a votar por nadie."], "otroSector": "La misma guía sirve para elecciones de delegados, de centros estudiantiles o de asociaciones."}$a60sld$::jsonb,62),
('como-se-organiza-una-eleccion-y-que-hacen-los-organismos-elector','derecho',array['sociedad']::text[],'Cómo se organiza una elección y qué hacen los organismos electorales','Explica cómo se organiza un proceso electoral y qué funciones cumple cada organismo electoral, desde la inscripción hasta la proclamación, en un esquema fácil de seguir.','Guía','~20 h',20,array['Organismos electorales','Elecciones']::text[],array['investigar','crear']::text[],'publicos',NULL,'ciencias politicas derecho sociologia administracion ingenieria de sistemas estadistica comunicaciones educacion lectura de normas. diagramas de procesos. sintesis. comunicacion neutral. portales de los organismos electorales. un editor de diagramas. un editor de documentos.',$a61sld${"id": "como-se-organiza-una-eleccion-y-que-hacen-los-organismos-elector", "area": "derecho", "areas2": ["sociedad"], "titulo": "Cómo se organiza una elección y qué hacen los organismos electorales", "resumen": "Explica cómo se organiza un proceso electoral y qué funciones cumple cada organismo electoral, desde la inscripción hasta la proclamación, en un esquema fácil de seguir.", "tipo": "Guía", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Organismos electorales", "Elecciones"], "intencion": ["investigar", "crear"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Ciencias Políticas", "Derecho", "Sociología", "Administración", "Ingeniería de Sistemas", "Estadística", "Comunicaciones", "Educación"], "problema": ["Detrás de cada elección hay un sistema con distintas instituciones que se encargan de aspectos como el padrón, la organización, la fiscalización y la resolución de controversias. Muchas personas no saben quién hace qué.", "Entender esa estructura permite seguir los procesos con más criterio y menos rumores."], "desarrollar": ["Con fuentes oficiales, describe las funciones de cada organismo electoral, las etapas del proceso y los mecanismos de control, y arma un diagrama con el recorrido de una elección.", "Prepara una guía de preguntas y respuestas, como ¿quién cuenta los votos? o ¿quién resuelve una impugnación?, con base en información oficial."], "ampliaciones": [{"titulo": "Tecnología electoral", "aporta": "describe qué herramientas tecnológicas se usan y cómo se auditan."}, {"titulo": "Participación observadora", "aporta": "explica cómo la ciudadanía puede observar el proceso."}, {"titulo": "Comparar sistemas", "aporta": "compara con el sistema de otro país de forma descriptiva."}], "objetivos": ["Conocer organismos electorales.", "Representar el proceso.", "Responder dudas frecuentes.", "Explicar con claridad."], "habilidades": ["Lectura de normas.", "Diagramas de procesos.", "Síntesis.", "Comunicación neutral."], "herramientas": ["Portales de los organismos electorales.", "Un editor de diagramas.", "Un editor de documentos."], "lineamientos": ["Mantén una mirada neutral: explica mecanismos y procedimientos, sin opinar sobre partidos, candidatos ni gestiones concretas.", "Verifica siempre en fuentes oficiales que la información siga vigente y cita su fecha, porque las normas y los procedimientos cambian.", "No evalúes la conducta de organismos ni resultados concretos: describe funciones y procedimientos con fuentes oficiales."], "otroSector": "El mismo esquema sirve para explicar cómo se organizan elecciones en un colegio o en una universidad."}$a61sld$::jsonb,63),
('guia-practica-de-derechos-y-deberes-de-la-ciudadania-en-la-vida','derecho',array['sociedad','educacion']::text[],'Guía práctica de derechos y deberes de la ciudadanía en la vida cotidiana','Crea una guía práctica que explique, con situaciones del día a día, qué derechos y deberes acompañan a la ciudadanía y cómo ejercerlos de manera informada.','Guía','3 a 4 semanas',26,array['Ciudadanía','Derechos y deberes']::text[],array['crear','investigar']::text[],'publicos',NULL,'derecho ciencias politicas educacion sociologia trabajo social comunicaciones psicologia administracion lectura de normas. sintesis. diseno de guias. comunicacion clara. portales oficiales. un editor de documentos o infografias. un formulario de opinion.',$a62sld${"id": "guia-practica-de-derechos-y-deberes-de-la-ciudadania-en-la-vida", "area": "derecho", "areas2": ["sociedad", "educacion"], "titulo": "Guía práctica de derechos y deberes de la ciudadanía en la vida cotidiana", "resumen": "Crea una guía práctica que explique, con situaciones del día a día, qué derechos y deberes acompañan a la ciudadanía y cómo ejercerlos de manera informada.", "tipo": "Guía", "tiempo": "3 a 4 semanas", "horas": 26, "etiquetas": ["Ciudadanía", "Derechos y deberes"], "intencion": ["crear", "investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Ciencias Políticas", "Educación", "Sociología", "Trabajo Social", "Comunicaciones", "Psicología", "Administración"], "problema": ["Se habla de derechos y deberes de forma abstracta, pero se viven en situaciones concretas: al comprar, al trabajar, al caminar por la ciudad o al usar un servicio público. Muchas personas no saben cuándo están ejerciendo un derecho ni cuándo se les exige un deber.", "Una guía con ejemplos cotidianos acerca el derecho a la vida diaria."], "desarrollar": ["Elige entre ocho y diez situaciones cotidianas, como una compra, un trámite, un trabajo o el uso de espacios públicos, y para cada una explica qué derechos y deberes entran en juego, qué dice la norma y qué pasos dar.", "Organiza todo en una guía ilustrada con un índice por situación, pruébala con diez personas y mejórala según sus dudas."], "ampliaciones": [{"titulo": "Versión para jóvenes", "aporta": "adapta lenguaje y ejemplos para adolescentes."}, {"titulo": "Versión digital", "aporta": "convierte la guía en una página web buscable."}, {"titulo": "Preguntas rápidas", "aporta": "agrega una sección de preguntas frecuentes."}], "objetivos": ["Reconocer derechos y deberes en situaciones reales.", "Citar fuentes oficiales.", "Diseñar una guía clara.", "Validarla con lectores."], "habilidades": ["Lectura de normas.", "Síntesis.", "Diseño de guías.", "Comunicación clara."], "herramientas": ["Portales oficiales.", "Un editor de documentos o infografías.", "Un formulario de opinión."], "lineamientos": ["Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a la entidad competente o a un abogado.", "Verifica siempre en fuentes oficiales que la información siga vigente y cita su fecha, porque las normas y los procedimientos cambian.", "Usa casos inventados y no incluyas datos de personas reales."], "otroSector": "La misma guía sirve para orientar a estudiantes de un colegio, a trabajadores nuevos o a migrantes."}$a62sld$::jsonb,64),
('comparando-procedimientos-administrativos-relacionados-con-un-mi','derecho',array['sociedad']::text[],'Comparando procedimientos administrativos relacionados con un mismo servicio','Compara cómo se realiza el mismo servicio, como obtener una licencia, un certificado o un permiso, en distintas instituciones o distritos, y descubre cuál es más simple y por qué.','Análisis','~22 h',22,array['Procedimientos','Comparación']::text[],array['investigar']::text[],'publicos',NULL,'derecho administracion ingenieria industrial ciencias politicas ingenieria de sistemas economia estadistica trabajo social analisis comparativo. lectura de procedimientos. diseno de criterios. propuestas de mejora. portales oficiales. hoja de calculo. un editor de graficos.',$a63sld${"id": "comparando-procedimientos-administrativos-relacionados-con-un-mi", "area": "derecho", "areas2": ["sociedad"], "titulo": "Comparando procedimientos administrativos relacionados con un mismo servicio", "resumen": "Compara cómo se realiza el mismo servicio, como obtener una licencia, un certificado o un permiso, en distintas instituciones o distritos, y descubre cuál es más simple y por qué.", "tipo": "Análisis", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Procedimientos", "Comparación"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Administración", "Ingeniería Industrial", "Ciencias Políticas", "Ingeniería de Sistemas", "Economía", "Estadística", "Trabajo Social"], "problema": ["A veces el mismo trámite se hace de forma muy distinta según la institución o el distrito: requisitos, costos y plazos cambian. Esa diferencia afecta el tiempo y el dinero de las personas.", "Compararlos permite ver buenas prácticas y propuestas de simplificación."], "desarrollar": ["Elige un servicio que se tramite en al menos tres lugares, reúne con fuentes oficiales sus requisitos, costos, plazos y canales, y arma una tabla comparativa.", "Calcula un puntaje de simplicidad con criterios claros, identifica cuál es más sencillo y por qué, y propón qué buenas prácticas podrían replicarse."], "ampliaciones": [{"titulo": "Costo total", "aporta": "calcula cuánto cuesta realmente cada versión del trámite."}, {"titulo": "Versión digital", "aporta": "compara trámites presenciales y en línea."}, {"titulo": "Recomendaciones", "aporta": "redacta una propuesta de estandarización."}], "objetivos": ["Reunir información comparable.", "Crear un puntaje de simplicidad.", "Identificar buenas prácticas.", "Proponer mejoras."], "habilidades": ["Análisis comparativo.", "Lectura de procedimientos.", "Diseño de criterios.", "Propuestas de mejora."], "herramientas": ["Portales oficiales.", "Hoja de cálculo.", "Un editor de gráficos."], "lineamientos": ["Mantén una mirada neutral: explica mecanismos y procedimientos, sin opinar sobre partidos, candidatos ni gestiones concretas.", "Verifica siempre en fuentes oficiales que la información siga vigente y cita su fecha, porque las normas y los procedimientos cambian.", "Describe las diferencias sin culpar a funcionarios y aclara que los requisitos pueden cambiar."], "otroSector": "La misma comparación sirve para evaluar procesos de admisión, de matrícula o de atención al cliente."}$a63sld$::jsonb,65),
('una-papeleta-de-transito-paso-a-paso-que-se-puede-hacer-y-en-que','derecho',array['ciudades']::text[],'Una papeleta de tránsito paso a paso: qué se puede hacer y en qué plazos','Explica qué pasa desde que se recibe una papeleta de tránsito: cómo consultarla, pagarla, reclamarla o impugnarla, y qué plazos y descuentos pueden aplicar.','Guía','~16 h',16,array['Tránsito','Sanciones']::text[],array['investigar','crear']::text[],'publicos',NULL,'derecho ingenieria civil administracion ingenieria de sistemas comunicaciones educacion ingenieria industrial trabajo social lectura de normas. diagramas de proceso. analisis de casos. redaccion clara. portales oficiales de transito. un editor de diagramas. hoja de calculo.',$a64sld${"id": "una-papeleta-de-transito-paso-a-paso-que-se-puede-hacer-y-en-que", "area": "derecho", "areas2": ["ciudades"], "titulo": "Una papeleta de tránsito paso a paso: qué se puede hacer y en qué plazos", "resumen": "Explica qué pasa desde que se recibe una papeleta de tránsito: cómo consultarla, pagarla, reclamarla o impugnarla, y qué plazos y descuentos pueden aplicar.", "tipo": "Guía", "tiempo": "~16 h", "horas": 16, "etiquetas": ["Tránsito", "Sanciones"], "intencion": ["investigar", "crear"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Ingeniería Civil", "Administración", "Ingeniería de Sistemas", "Comunicaciones", "Educación", "Ingeniería Industrial", "Trabajo Social"], "problema": ["Recibir una papeleta genera dudas: ¿es válida?, ¿cuánto tiempo hay para pagar?, ¿se puede reclamar?, ¿qué pasa si no se paga? Mucha gente paga de más, deja vencer plazos o cae en trámites innecesarios por no conocer el procedimiento.", "Un mapa claro del proceso ayuda a decidir con calma."], "desarrollar": ["Con fuentes oficiales, describe las etapas: notificación, consulta, pago, descuentos, reclamo y recurso, y arma un diagrama con plazos y autoridades.", "Redacta cinco casos inventados, como una papeleta por exceso de velocidad o una mal registrada, y explica qué opciones tendría la persona en cada uno."], "ampliaciones": [{"titulo": "Calculadora de plazos", "aporta": "arma una hoja que calcule fechas límite desde la notificación."}, {"titulo": "Errores frecuentes", "aporta": "lista motivos comunes de reclamo, como datos mal consignados."}, {"titulo": "Educación vial", "aporta": "enlaza con una guía de prevención de infracciones."}], "objetivos": ["Conocer el procedimiento.", "Representarlo con plazos.", "Aplicarlo a casos.", "Explicar con claridad."], "habilidades": ["Lectura de normas.", "Diagramas de proceso.", "Análisis de casos.", "Redacción clara."], "herramientas": ["Portales oficiales de tránsito.", "Un editor de diagramas.", "Hoja de cálculo."], "lineamientos": ["Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a la entidad competente o a un abogado.", "Verifica siempre en fuentes oficiales que la información siga vigente y cita su fecha, porque las normas, plazos y montos cambian.", "Trabaja con casos inventados y sin datos personales de nadie."], "otroSector": "El mismo mapa sirve para multas municipales, sanciones de consumo o infracciones de otro tipo."}$a64sld$::jsonb,66),
('los-plazos-legales-de-la-vida-cotidiana-que-es-la-prescripcion-y','derecho',array['educacion']::text[],'Los plazos legales de la vida cotidiana: qué es la prescripción y por qué importa','Explica por qué los derechos y los reclamos tienen plazos, qué significa que algo prescriba y cuáles son ejemplos de plazos que afectan a una persona común.','Guía','~18 h',18,array['Plazos','Prescripción']::text[],array['investigar','crear']::text[],'publicos',NULL,'derecho administracion contabilidad educacion ingenieria de sistemas comunicaciones economia psicologia lectura de normas. sintesis. diseno visual. organizacion del tiempo. portales oficiales. hoja de calculo. un editor de infografias.',$a65sld${"id": "los-plazos-legales-de-la-vida-cotidiana-que-es-la-prescripcion-y", "area": "derecho", "areas2": ["educacion"], "titulo": "Los plazos legales de la vida cotidiana: qué es la prescripción y por qué importa", "resumen": "Explica por qué los derechos y los reclamos tienen plazos, qué significa que algo prescriba y cuáles son ejemplos de plazos que afectan a una persona común.", "tipo": "Guía", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Plazos", "Prescripción"], "intencion": ["investigar", "crear"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Administración", "Contabilidad", "Educación", "Ingeniería de Sistemas", "Comunicaciones", "Economía", "Psicología"], "problema": ["Muchos reclamos se pierden no porque la persona no tuviera razón, sino porque dejó pasar el tiempo. Plazos para reclamar una garantía, impugnar una multa o cobrar una deuda son parte de la vida diaria, pero casi nadie los conoce.", "Entender la idea de plazo y prescripción ayuda a actuar a tiempo."], "desarrollar": ["Con fuentes oficiales, explica qué es un plazo, qué es prescripción y caducidad, y reúne diez ejemplos de plazos cotidianos, como consumo, tránsito, trabajo y trámites, indicando su fuente.", "Crea un calendario visual de plazos con ejemplos y una lista de hábitos para no perderlos, como guardar comprobantes y anotar fechas."], "ampliaciones": [{"titulo": "Recordatorios", "aporta": "diseña un modelo de agenda para no dejar vencer plazos."}, {"titulo": "Casos", "aporta": "redacta tres casos inventados donde se pierde un derecho por demora."}, {"titulo": "Cómo contar un plazo", "aporta": "explica días hábiles y calendario con ejemplos."}], "objetivos": ["Comprender plazos y prescripción.", "Reunir ejemplos cotidianos.", "Diseñar un calendario visual.", "Proponer hábitos."], "habilidades": ["Lectura de normas.", "Síntesis.", "Diseño visual.", "Organización del tiempo."], "herramientas": ["Portales oficiales.", "Hoja de cálculo.", "Un editor de infografías."], "lineamientos": ["Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a la entidad competente o a un abogado.", "Verifica siempre en fuentes oficiales que la información siga vigente y cita su fecha, porque las normas, plazos y montos cambian.", "Los plazos varían según el caso y la norma: presenta cada uno con su fuente y fecha de consulta."], "otroSector": "La misma guía sirve para plazos en contratos, en trámites universitarios o en proyectos."}$a65sld$::jsonb,67)
